import{z as A,x as B,o as n,c as d,q as r,j as E,D as e,d as s,s as o,S as l,b as i}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"AIMD 与 Chiu–Jain","description":"","frontmatter":{"title":"AIMD 与 Chiu–Jain","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/aimd-dynamics.md","filePath":"cs/aimd-dynamics.md","lastUpdated":1791063341000}'),p={name:"cs/aimd-dynamics.md"};function C(D,a,c,T,h,m){const t=B("Mermaid");return n(),d("div",null,[a[2]||(a[2]=r('<h1 id="aimd-与-chiu–jain" tabindex="-1">AIMD 与 Chiu–Jain <a class="header-anchor" href="#aimd-与-chiu–jain" aria-label="Permalink to &quot;AIMD 与 Chiu–Jain&quot;">​</a></h1><div class="epigraph"><p>加性增、乘性减使共享瓶颈的流在公平与效率之间收敛；Chiu–Jain 用二维相位图说明为何 MIMD 会漂。</p><footer>—— 据 Chiu and Jain, Analysis of the Increase and Decrease Algorithms, Computer Networks 1989；Jacobson, 1988 整理</footer></div><p>主干<a href="/cs/tcp-congestion">拥塞控制</a> 已用 AIMD。<a href="/cs/roce-lossless">上一课</a> 结束转发面。缺口是<strong>为什么是 AI 而不是 MI</strong>：两用户相位图、公平线与效率线。本课不把快重传状态机写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两流共享容量 \\(C\\)。效率线 \\(x_1+x_2=C\\)，公平线 \\(x_1=x_2\\)。加性增：平行于公平线走向效率；乘性减：沿过原点射线退回。MIMD 增沿射线走，到不了公平。AIAD 在效率线附近振荡不收敛。数据中心 DCTCP 仍是乘性，只是减得更温和。广域卫星 BDP 大使 AIMD 探到 \\(C\\) 的时间变长，不改几何。</p><p><span class="marginnote">直觉类比：把相位图想成两人分一块大小为 \\(C\\) 的蛋糕——效率线是「别浪费」，公平线是「要平分」。加性增是两人每次各多要一块，差距不变、整体逼近蛋糕边；乘性减是两人把手里的量同时砍半，比例不变、落点回到过原点的射线上，反而更靠近平分线。一增一减，锯齿越锯越靠交点。</span></p><p>不要把 Jain 公平指数写成必须每课计算，这里只要相位图直觉。</p><p><span class="marginnote">Chiu–Jain 1989。同步假设理想化；延迟 ACK、不同 RTT 后课会破公平。本课钉同 RTT 同步。</span></p><h3 id="同-rtt-才有那张相位图" tabindex="-1">同 RTT 才有那张相位图 <a class="header-anchor" href="#同-rtt-才有那张相位图" aria-label="Permalink to &quot;同 RTT 才有那张相位图&quot;">​</a></h3><p>AI 走向效率，MD 走向公平。MIMD 漂。不同 RTT 与 ACK 压缩会偏离交点，后课再破。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画相位图：效率、公平、AIMD 轨迹。对照 PFC：链路暂停不是 AIMD，无公平定理。对照 WFQ：调度器显式公平，AIMD 是端到端隐式。</p><p><span class="marginnote">术语翻译：MIMD 就是「乘性增、乘性减」——每轮按固定比例放大或缩小速率（如都乘 2 或乘 0.5）。听起来与 AIMD 相似，但比例操作不改变两流的差距比例，落点始终在过原点的同一条射线上，永远碰不到公平线 \\(x_1=x_2\\)。</span></p>',13)),(n(),E(l,null,{default:e(()=>[o(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20AI%5B%22%E5%8A%A0%E6%80%A7%E5%A2%9E%22%5D%20--%3E%20EFF%5B%22%E9%9D%A0%E8%BF%91%E6%95%88%E7%8E%87%E7%BA%BF%22%5D%0A%20%20MD%5B%22%E4%B9%98%E6%80%A7%E5%87%8F%22%5D%20--%3E%20FAIR%5B%22%E9%9D%A0%E8%BF%91%E5%85%AC%E5%B9%B3%E7%BA%BF%22%5D%0A%20%20AIMD%5B%22%E4%BA%A4%E6%9B%BF%22%5D%20--%3E%20CONV%5B%22%E6%94%B6%E6%95%9B%E4%BA%A4%E7%82%B9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[s("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"Reno 每 RTT 约加一 MSS，丢则减半，是 AIMD 实例。CUBIC 用时间立方，仍有乘性事件。ECN 把「减」从丢包提前，几何类似。多瓶颈与不同 RTT 使交点偏离，后课 RTT 不公平。",-1)),a[5]||(a[5]=i("p",null,"落到一条真实 TCP 流上，相位图的锯齿就是下面这个不断重复的周期：",-1)),(n(),E(l,null,{default:e(()=>[o(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22cwnd%20%E8%BE%83%E5%B0%8F%EF%BC%8C%E6%85%A2%E6%B6%A8%E9%98%B6%E6%AE%B5%22%5D%20--%3E%20G%5B%22%E6%AF%8F%20RTT%20%E5%8A%A0%201%20MSS%EF%BC%88AI%EF%BC%9A%E5%B9%B3%E8%A1%8C%E5%85%AC%E5%B9%B3%E7%BA%BF%E4%B8%8A%E7%A7%BB%EF%BC%89%22%5D%0A%20%20G%20--%3E%20Q%7B%22%E9%A1%B6%E5%88%B0%E6%95%88%E7%8E%87%E7%BA%BF%E5%B9%B6%E6%94%B6%E5%88%B0%E4%B8%A2%E5%8C%85%2FECN%20%E4%BF%A1%E5%8F%B7%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%BF%98%E6%B2%A1%E5%88%B0%22%7C%20G%0A%20%20Q%20--%3E%7C%22%E5%88%B0%E4%BA%86%22%7C%20H%5B%22cwnd%20%E5%87%8F%E5%8D%8A%EF%BC%88MD%EF%BC%9A%E6%B2%BF%E8%BF%87%E5%8E%9F%E7%82%B9%E5%B0%84%E7%BA%BF%E9%80%80%E5%9B%9E%EF%BC%89%22%5D%0A%20%20H%20--%3E%20S%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">数字实例：cwnd 为 40 KB（约 20 个 1460 字节的 MSS）时丢包，减半后只剩 10 个 MSS；之后每 RTT 只加回 1 个，爬回 20 个要 10 个 RTT。「涨得慢、砍得快」正是网速测试里锯齿波形的来源。</span></p><p>与交换机 VOQ 匹配对照：一个在端，一个在跳；都在分配 \\(C\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证一般 \\(n\\) 流的全部 Lyapunov。快速重传与恢复是下一课。后课默认：同 RTT 下 AIMD 收敛到公平有效；其它增减组合不。</p><p>实际 ACK 压缩会让「每 RTT 加一」变成突发，几何仍近似。</p><p>下一课<a href="/cs/fast-retransmit-recovery">快速重传与恢复</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AIMD 在效率–公平图上收敛。</li><li>MIMD/AIAD 不提供同样保证。</li><li>TCP 减半是 MD；DCTCP 是更小的 MD。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Chiu–Jain, 1989；Jacobson, 1988。</li></ul>',8))])}const F=A(p,[["render",C]]);export{M as __pageData,F as default};
